#!/usr/bin/env python3
import zipfile, xml.etree.ElementTree as ET, re, json, hashlib, html, os, datetime, sys
from pathlib import Path

SRC = Path(sys.argv[1] if len(sys.argv)>1 else '/mnt/data/Minecraft Recommendations Vault — Master Tracker')
OUT = Path(sys.argv[2] if len(sys.argv)>2 else '/mnt/data/Minecraft Recommendations Vault - Explorer.html')
SOURCE_ID='1N5rGN1E6jk3LMcPLNoRVWi3-8QmFtOikBguvoCaAMMg'
SOURCE_URL=f'https://docs.google.com/spreadsheets/d/{SOURCE_ID}/edit'
SOURCE_MODIFIED='2026-08-29T22:28:18.260Z'
GENERATOR_VERSION='recommendations-explorer/1.0.0'
NS={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

def col_idx(ref):
    m=re.match(r'([A-Z]+)',ref)
    n=0
    for ch in m.group(1): n=n*26+ord(ch)-64
    return n-1

def parse_xlsx(path):
    with zipfile.ZipFile(path) as z:
        shared=[]
        if 'xl/sharedStrings.xml' in z.namelist():
            root=ET.fromstring(z.read('xl/sharedStrings.xml'))
            for si in root.findall('m:si',NS):
                shared.append(''.join(t.text or '' for t in si.iter('{%s}t'%NS['m'])))
        wb=ET.fromstring(z.read('xl/workbook.xml'))
        relroot=ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
        rels={r.attrib['Id']:r.attrib['Target'] for r in relroot}
        out=[]
        for sh in wb.find('m:sheets',NS):
            name=sh.attrib['name']; rid=sh.attrib['{%s}id'%NS['r']]; target=rels[rid]
            if target.startswith('/'): target=target.lstrip('/')
            elif not target.startswith('xl/'): target='xl/'+target
            root=ET.fromstring(z.read(target))
            rows=[]
            for row in root.findall('.//m:sheetData/m:row',NS):
                vals=[]
                for c in row.findall('m:c',NS):
                    idx=col_idx(c.attrib['r'])
                    while len(vals)<=idx: vals.append('')
                    typ=c.attrib.get('t'); v=c.find('m:v',NS); isel=c.find('m:is',NS)
                    val=''
                    if typ=='s' and v is not None: val=shared[int(v.text)]
                    elif typ=='inlineStr' and isel is not None: val=''.join(t.text or '' for t in isel.iter('{%s}t'%NS['m']))
                    elif typ=='b' and v is not None: val='TRUE' if v.text=='1' else 'FALSE'
                    elif v is not None: val=v.text or ''
                    vals[idx]=val
                while vals and vals[-1]=='': vals.pop()
                if any(str(x).strip() for x in vals): rows.append(vals)
            out.append({'name':name,'rows':rows})
        return out

def norm(s): return re.sub(r'\s+',' ',str(s or '')).strip()

def row_id(sheet, idx, row):
    seed=f'{sheet}\0{idx}\0{row[0] if row else ""}'
    return hashlib.sha1(seed.encode()).hexdigest()[:14]

def enrich(sheets):
    for s in sheets:
        for i,r in enumerate(s['rows']):
            s.setdefault('ids',[]).append(row_id(s['name'],i,r))
    return sheets

sha=hashlib.sha256(SRC.read_bytes()).hexdigest()
sheets=enrich(parse_xlsx(SRC))
master=next(s for s in sheets if s['name']=='Master Catalog')
master_count=max(0,len(master['rows'])-1)
all_nonblank=sum(len(s['rows']) for s in sheets)
payload={'source':{'title':'Minecraft Recommendations Vault — Master Tracker','driveId':SOURCE_ID,'url':SOURCE_URL,'modifiedTime':SOURCE_MODIFIED,'exportSha256':sha,'exportBytes':SRC.stat().st_size},'build':{'generator':GENERATOR_VERSION,'builtAt':datetime.datetime.now(datetime.timezone.utc).isoformat().replace('+00:00','Z'),'sheetCount':len(sheets),'sourceRowCount':all_nonblank,'masterItemCount':master_count},'sheets':sheets}
payload_json=json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</script>','<\\/script>')

CSS=r'''
:root{color-scheme:dark;--bg:#090d13;--panel:#111823;--panel2:#151f2d;--text:#edf4ff;--muted:#9eb0c7;--line:#243248;--accent:#78b7ff;--accent2:#9ee6c3;--warn:#ffd486;--danger:#ff9f9f;--shadow:0 16px 50px rgba(0,0,0,.28)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 20% 0,#142338 0,#090d13 38rem);color:var(--text);font:14px/1.45 ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,sans-serif}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}button,input,select,textarea{font:inherit}.app{max-width:1760px;margin:auto;padding:18px}.hero{background:linear-gradient(135deg,rgba(120,183,255,.16),rgba(158,230,195,.08));border:1px solid var(--line);border-radius:20px;padding:20px;box-shadow:var(--shadow)}h1{font-size:clamp(24px,4vw,42px);line-height:1;margin:0 0 8px}.sub{color:var(--muted);max-width:1000px}.stats{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.pill,.chip{border:1px solid var(--line);background:#0e1621;border-radius:999px;padding:6px 10px;color:var(--muted)}.pill strong{color:var(--text)}.toolbar{position:sticky;top:0;z-index:20;background:rgba(9,13,19,.93);backdrop-filter:blur(12px);padding:12px 0;display:grid;grid-template-columns:minmax(230px,1fr) auto auto;gap:8px}.search{width:100%;border:1px solid var(--line);background:var(--panel);color:var(--text);padding:11px 14px;border-radius:12px;outline:none}.search:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(120,183,255,.12)}.btn{border:1px solid var(--line);background:var(--panel);color:var(--text);padding:9px 11px;border-radius:10px;cursor:pointer}.btn:hover{border-color:#405774}.btn.active{background:#1b3150;border-color:#4c7cb8}.layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:14px}.side{align-self:start;position:sticky;top:70px;max-height:calc(100vh - 90px);overflow:auto;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:10px}.tabs{display:flex;flex-direction:column;gap:4px}.tab{width:100%;text-align:left}.tab small{float:right;color:var(--muted)}.filters{margin-top:10px;border-top:1px solid var(--line);padding-top:10px}.filters label{display:block;color:var(--muted);font-size:12px;margin:8px 0 3px}.filters select,.filters input{width:100%;border:1px solid var(--line);background:#0b111a;color:var(--text);padding:8px;border-radius:9px}.main{min-width:0}.section-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin:6px 0 10px}.section-head h2{margin:0;font-size:22px}.muted{color:var(--muted)}.leader-grid,.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px}.leader,.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:13px;min-width:0}.leader:hover,.card:hover{border-color:#3d5270}.card h3{font-size:16px;margin:0 0 6px}.card .meta{display:flex;gap:5px;flex-wrap:wrap}.card .desc{color:var(--muted);margin-top:8px;white-space:normal;overflow-wrap:anywhere}.card-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.iconbtn{padding:6px 8px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:14px;background:var(--panel)}table{border-collapse:collapse;width:100%;min-width:1100px}th,td{padding:9px 10px;text-align:left;vertical-align:top;border-bottom:1px solid #1d2a3c;max-width:480px;overflow-wrap:anywhere}th{position:sticky;top:0;background:#152033;color:#cfe0f7;z-index:2;font-size:12px}tr:hover td{background:#101b29}.empty{padding:30px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:14px}.drawer{position:fixed;inset:0 0 0 auto;width:min(650px,100%);background:#0c121b;border-left:1px solid var(--line);z-index:50;box-shadow:-20px 0 60px rgba(0,0,0,.4);padding:18px;overflow:auto;transform:translateX(105%);transition:transform .18s ease}.drawer.open{transform:none}.drawer .close{float:right}.detail-grid{display:grid;grid-template-columns:150px 1fr;gap:8px;border-top:1px solid var(--line);padding-top:12px}.detail-grid dt{color:var(--muted)}.detail-grid dd{margin:0;overflow-wrap:anywhere}.compare{position:fixed;bottom:12px;left:50%;transform:translateX(-50%);z-index:30;background:#0e1621;border:1px solid var(--line);border-radius:14px;padding:9px 12px;box-shadow:var(--shadow);display:none;max-width:calc(100vw - 24px)}.compare.show{display:flex;gap:8px;align-items:center}.notes{width:100%;min-height:90px;background:#090e15;color:var(--text);border:1px solid var(--line);border-radius:10px;padding:9px}.provenance{margin-top:18px;background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px;color:var(--muted)}.kbd{font-family:ui-monospace,monospace;border:1px solid var(--line);background:#0a111b;padding:1px 5px;border-radius:5px}.hidden{display:none!important}@media(max-width:900px){.layout{grid-template-columns:1fr}.side{position:static;max-height:none}.tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.toolbar{grid-template-columns:1fr auto}.toolbar .secondary{display:none}.detail-grid{grid-template-columns:1fr}.leader-grid,.cards{grid-template-columns:1fr}}@media(max-width:520px){.app{padding:10px}.tabs{grid-template-columns:1fr}.hero{padding:16px}.toolbar{top:0}.btn{padding:8px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
'''

JS=r'''
const DB=JSON.parse(document.getElementById('vault-data').textContent);
const qs=s=>document.querySelector(s), qsa=s=>[...document.querySelectorAll(s)];
const store=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}, save=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let state={sheet:'Dashboard',q:'',view:'table',sort:'',dir:1,filters:{},favorites:new Set(store('mrv:favs',[])),notes:store('mrv:notes',{}),recent:store('mrv:recent',[]),compare:[]};
const sheets=Object.fromEntries(DB.sheets.map(s=>[s.name,s]));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isUrl=s=>/^https?:\/\//i.test(String(s||''));
function headers(s){return s.rows[0]||[]}
function firstUrl(r){return r.find(isUrl)||''}
function masterCols(){let h=headers(sheets['Master Catalog']);let m={};h.forEach((x,i)=>m[x]=i);return m} const MC=masterCols();
function rowObj(s,r,i){let h=headers(s),o={_sheet:s.name,_index:i,_id:s.ids[i]};h.forEach((k,j)=>{if(k)o[k]=r[j]??''});return o}
function masterRows(){let s=sheets['Master Catalog'];return s.rows.slice(1).map((r,i)=>rowObj(s,r,i+1))}
function linkName(o){let name=o.Project||o['Launcher / Manager']||o['Tool / Project']||o['Tool / Method']||o.Category||Object.values(o).find(v=>v&&!isUrl(v))||'Open';let u=o['Official / Primary Project Link']||o['Official URL']||o.URL||Object.values(o).find(isUrl)||'';return u?`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(name)}</a>`:esc(name)}
function makeTabs(){qs('#tabs').innerHTML=DB.sheets.map(s=>`<button class="btn tab ${state.sheet===s.name?'active':''}" data-sheet="${esc(s.name)}">${esc(s.name)} <small>${Math.max(0,s.rows.length-1)}</small></button>`).join('');qsa('[data-sheet]').forEach(b=>b.onclick=()=>{state.sheet=b.dataset.sheet;render()})}
function opts(key){let vals=[...new Set(masterRows().map(o=>o[key]).filter(Boolean))].sort((a,b)=>a.localeCompare(b));return `<option value="">All</option>`+vals.map(v=>`<option>${esc(v)}</option>`).join('')}
function makeFilters(){qs('#filters').innerHTML=`<label>Edition</label><select data-filter="Edition">${opts('Edition')}</select><label>Minecraft version</label><input data-filter="Minecraft Version(s)" placeholder="e.g. 1.20.1"><label>Loader / channel</label><input data-filter="Loader / Channel" placeholder="Forge, NeoForge…"><label>Category / tags</label><input data-filter="Category / Tags" placeholder="Performance, mobs…"><label>Status</label><input data-filter="Status" placeholder="INSTALL, WATCH…"><label>Client only?</label><select data-filter="Client Only?">${opts('Client Only?')}</select><label>Safe to remove?</label><select data-filter="Safe to Remove?">${opts('Safe to Remove?')}</select><label>Sort</label><select id="sort"><option value="">Sheet order</option>${['Project','Release / Update Date','Maturity','Status','Last Verification / Evidence'].map(x=>`<option>${esc(x)}</option>`).join('')}</select>`;qsa('[data-filter]').forEach(el=>{el.value=state.filters[el.dataset.filter]||'';el.oninput=()=>{state.filters[el.dataset.filter]=el.value;renderMain()}});qs('#sort').value=state.sort;qs('#sort').onchange=e=>{state.sort=e.target.value;renderMain()}}
function matchObj(o){let q=state.q.toLowerCase();if(q&&!Object.values(o).some(v=>String(v).toLowerCase().includes(q)))return false;for(let[k,v]of Object.entries(state.filters)){if(v&&!String(o[k]||'').toLowerCase().includes(v.toLowerCase()))return false}return true}
function visibleMaster(){let a=masterRows().filter(matchObj);if(state.sort)a.sort((x,y)=>String(x[state.sort]||'').localeCompare(String(y[state.sort]||''),undefined,{numeric:true})*state.dir);return a}
function favorite(id){if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);save('mrv:favs',[...state.favorites]);renderMain()}
function addCompare(id){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<4)state.compare.push(id);renderCompare();renderMain()}
function openDetail(id){let o=masterRows().find(x=>x._id===id);if(!o)return;state.recent=[id,...state.recent.filter(x=>x!==id)].slice(0,12);save('mrv:recent',state.recent);qs('#drawerTitle').innerHTML=linkName(o);let entries=Object.entries(o).filter(([k,v])=>!k.startsWith('_')&&v);qs('#detail').innerHTML='<dl class="detail-grid">'+entries.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${isUrl(v)?`<a href="${esc(v)}" target="_blank" rel="noopener">${esc(v)}</a>`:esc(v)}</dd>`).join('')+'</dl><h3>Private notes (browser-local)</h3><textarea class="notes" id="note">'+esc(state.notes[id]||'')+'</textarea>';qs('#note').oninput=e=>{state.notes[id]=e.target.value;save('mrv:notes',state.notes)};qs('#drawer').classList.add('open')}
function card(o){let desc=o.Notes||o['Compatibility / Risk Notes']||o['Why / Notes']||'';let meta=[o.Edition,o['Current Version / Line'],o['Loader / Channel'],o.Status].filter(Boolean);return `<article class="card"><h3>${linkName(o)}</h3><div class="meta">${meta.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><div class="desc">${esc(desc)}</div><div class="card-actions"><button class="btn iconbtn" onclick="openDetail('${o._id}')">Details</button><button class="btn iconbtn" onclick="favorite('${o._id}')">${state.favorites.has(o._id)?'★ Favorite':'☆ Favorite'}</button><button class="btn iconbtn" onclick="addCompare('${o._id}')">${state.compare.includes(o._id)?'✓ Compare':'+ Compare'}</button></div></article>`}
function tableFor(s,rows){let h=headers(s);return `<div class="table-wrap"><table><thead><tr>${h.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map((r,ri)=>`<tr>${h.map((x,j)=>{let v=r[j]??'';if(j===0){let u=r.find(isUrl)||'';if(s.name==='Master Catalog')u=r[20]||u;return `<td>${u?`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(v)}</a>`:esc(v)}</td>`}return `<td>${isUrl(v)?`<a href="${esc(v)}" target="_blank" rel="noopener">${esc(v)}</a>`:esc(v)}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
function renderLeaders(){let s=sheets['Category Leaders'];let h=headers(s);let rows=s.rows.slice(1);return `<div class="leader-grid">${rows.map(r=>`<article class="leader"><strong>#${esc(r[0])} ${esc(r[1])}</strong><div style="margin-top:6px">${esc(r[2])}</div><div class="muted">${esc(r[4]||'')}</div><div style="margin-top:7px">${esc(r[6]||'')}</div></article>`).join('')}</div>`}
function renderMain(){let box=qs('#content'),s=sheets[state.sheet];qs('#sheetTitle').textContent=state.sheet;let count=0;if(state.sheet==='Master Catalog'){let a=visibleMaster();count=a.length;box.innerHTML=state.view==='cards'?`<div class="cards">${a.map(card).join('')}</div>`:tableFor(s,a.map(o=>s.rows[o._index]));}else if(state.sheet==='Category Leaders'&&!state.q){count=s.rows.length-1;box.innerHTML=renderLeaders()}else{let rows=s.rows.slice(state.sheet==='Dashboard'||state.sheet==='Monster Girls'||state.sheet==='Sources & Rules'?0:1).filter(r=>!state.q||r.some(v=>String(v).toLowerCase().includes(state.q.toLowerCase())));count=rows.length;box.innerHTML=rows.length?tableFor(s,rows):'<div class="empty">No rows match this search.</div>'}qs('#matchCount').textContent=`${count} shown`;qs('#viewCards').classList.toggle('active',state.view==='cards');qs('#viewTable').classList.toggle('active',state.view==='table');renderCompare()}
function renderCompare(){let el=qs('#compare');let rows=masterRows().filter(o=>state.compare.includes(o._id));el.classList.toggle('show',rows.length>0);el.innerHTML=rows.length?`<span><strong>Compare ${rows.length}/4</strong> · ${rows.map(o=>esc(o.Project)).join(' · ')}</span><button class="btn" onclick="showCompare()">Open</button><button class="btn" onclick="state.compare=[];renderCompare();renderMain()">Clear</button>`:''}
function showCompare(){let rows=masterRows().filter(o=>state.compare.includes(o._id));let keys=['Project','Edition','Current Version / Line','Minecraft Version(s)','Loader / Channel','Status','Client Only?','Safe to Remove?','Compatibility / Risk Notes'];qs('#drawerTitle').textContent='Compare';qs('#detail').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Field</th>${rows.map(o=>`<th>${esc(o.Project)}</th>`).join('')}</tr></thead><tbody>${keys.map(k=>`<tr><th>${esc(k)}</th>${rows.map(o=>`<td>${esc(o[k]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;qs('#drawer').classList.add('open')}
function exportData(kind){let rows=visibleMaster(),h=headers(sheets['Master Catalog']);let text,mime,name;if(kind==='json'){text=JSON.stringify(rows.map(o=>Object.fromEntries(h.map(k=>[k,o[k]||'']))),null,2);mime='application/json';name='minecraft-recommendations-filtered.json'}else{text=[h,...rows.map(o=>h.map(k=>o[k]||''))].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');mime='text/csv';name='minecraft-recommendations-filtered.csv'}let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:mime}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function render(){makeTabs();qs('#filtersWrap').classList.toggle('hidden',state.sheet!=='Master Catalog');renderMain()}
function init(){qs('#globalSearch').oninput=e=>{state.q=e.target.value;renderMain()};qs('#viewCards').onclick=()=>{state.view='cards';renderMain()};qs('#viewTable').onclick=()=>{state.view='table';renderMain()};qs('#closeDrawer').onclick=()=>qs('#drawer').classList.remove('open');qs('#exportJson').onclick=()=>exportData('json');qs('#exportCsv').onclick=()=>exportData('csv');document.addEventListener('keydown',e=>{if(e.key==='/'&&document.activeElement.tagName!=='INPUT'&&document.activeElement.tagName!=='TEXTAREA'){e.preventDefault();qs('#globalSearch').focus()}if(e.key==='Escape')qs('#drawer').classList.remove('open')});makeFilters();render();let mc=masterRows();qs('#statMaster').textContent=mc.length;qs('#statSheets').textContent=DB.sheets.length;qs('#statHash').textContent=DB.source.exportSha256.slice(0,12);qs('#builtAt').textContent=DB.build.builtAt;qs('#sourceModified').textContent=DB.source.modifiedTime;qs('#sourceLink').href=DB.source.url;window.__EXPLORER_TEST__=()=>{let ids=mc.map(x=>x._id);let urls=mc.map(o=>o['Official / Primary Project Link']).filter(Boolean);return {masterCount:mc.length,expected:DB.build.masterItemCount,uniqueIds:new Set(ids).size===ids.length,sheetCount:DB.sheets.length,allSourceSheets:DB.sheets.every(s=>s.rows.length>0),officialLinksHttp:urls.every(isUrl),searchTest:mc.filter(o=>Object.values(o).some(v=>String(v).toLowerCase().includes('forge'))).length>0,filtersAvailable:qsa('[data-filter]').length>=6,controls:{favorites:typeof favorite==='function',notes:true,compare:typeof addCompare==='function',exports:typeof exportData==='function'},errors:[]}};let t=window.__EXPLORER_TEST__();qs('#selftest').dataset.result=JSON.stringify(t)}
window.openDetail=openDetail;window.favorite=favorite;window.addCompare=addCompare;window.showCompare=showCompare;document.addEventListener('DOMContentLoaded',init);
'''

HTML=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Minecraft Recommendations Vault - Explorer</title><style>{CSS}</style></head><body><div class="app"><header class="hero"><h1>Minecraft Recommendations Vault</h1><p class="sub">Offline-first Explorer for the canonical recommendations database. The Google Sheet remains authoritative; this build is a complete browse layer with no row caps, viewport culling, or hidden off-screen dataset.</p><div class="stats"><span class="pill"><strong id="statMaster"></strong> master projects</span><span class="pill"><strong id="statSheets"></strong> source sheets</span><span class="pill">source SHA-256 <strong id="statHash"></strong>…</span><span class="pill">keyboard <span class="kbd">/</span> search · <span class="kbd">Esc</span> close</span></div></header><div class="toolbar"><input id="globalSearch" class="search" type="search" placeholder="Search every field in the active view…" aria-label="Global search"><div><button id="viewTable" class="btn active">Table</button><button id="viewCards" class="btn">Cards</button></div><div class="secondary"><button id="exportCsv" class="btn">Export CSV</button><button id="exportJson" class="btn">Export JSON</button></div></div><div class="layout"><aside class="side"><nav id="tabs" class="tabs" aria-label="Source sheets"></nav><div id="filtersWrap" class="filters"><strong>Master Catalog filters</strong><div id="filters"></div></div></aside><main class="main"><div class="section-head"><h2 id="sheetTitle">Dashboard</h2><span id="matchCount" class="muted"></span></div><div id="content"></div><section class="provenance"><strong>Build provenance</strong><div>Authoritative source: <a id="sourceLink" target="_blank" rel="noopener">Minecraft Recommendations Vault — Master Tracker</a></div><div>Source modified: <span id="sourceModified"></span> · Explorer built: <span id="builtAt"></span></div><div>Source export SHA-256: <code>{sha}</code> · Generator: <code>{GENERATOR_VERSION}</code></div><div>All {len(sheets)} source sheets and {all_nonblank} nonblank source rows are embedded in this single file. Master Catalog: {master_count} project rows.</div></section></main></div></div><aside id="drawer" class="drawer" aria-label="Project details"><button id="closeDrawer" class="btn close">Close</button><h2 id="drawerTitle">Details</h2><div id="detail"></div></aside><div id="compare" class="compare"></div><div id="selftest" class="hidden"></div><script id="vault-data" type="application/json">{payload_json}</script><script>{JS}</script></body></html>'''
